registerCombo({
  comboId: 498,
  members: ["Ring_Of_Wise_King", "Lunar_Rainbow"],
  onActive(ctx) {
    let $r, $a;
    $r = ctx.getequiprefinerycnt("EQI_HEAD_TOP");
    if ($r < 4) {
      $a = 4;
    } else {
      $a = ctx.min($r, 10);
    }
    ctx.bonus3("bAutoSpell", "WZ_WATERBALL", $a, ($a * 10));

  },
});

registerCombo({
  comboId: 499,
  members: ["Celine_Brooch", "Lush_Rose"],
  onActive(ctx) {
    let $r, $a;
    $r = ctx.getequiprefinerycnt("EQI_HEAD_TOP");
    $a = ctx.min($r, 10);
    ctx.bonus("bAllStats", $a);
    ctx.bonus("bFixedCastrate", -50);
    if ($r >= 7) {
      ctx.bonus2("bMagicAddClass", "Class_Boss", 20);
    }

  },
});

